import type { ReactNode } from 'react'
import { Progress } from '@base-ui/react/progress'
import { cn } from '@/lib/utils'
import styles from './ProgressBar.module.css'

export interface ProgressBarProps extends Omit<Progress.Root.Props, 'value' | 'children' | 'className' | 'render'> {
  value?: number
  /** The spec's `maxValue`. */
  max?: number
  size?: 'sm' | 'md' | 'lg'
  isRounded?: boolean
  variant?: 'primary' | 'accent' | 'secondary' | 'destructive'
  /** Progress is happening but how much is unknown: a sliding bar. */
  isIndeterminate?: boolean
  /** Show the value ("70%") after the bar. */
  showValueLabel?: boolean
  /** A visible label above the bar; also its accessible name. */
  label?: ReactNode
  /** The accessible name when there is no visible `label`. */
  'aria-label'?: string
  className?: string
}

export function ProgressBar({
  value = 0,
  max = 100,
  size = 'md',
  isRounded = false,
  variant = 'primary',
  isIndeterminate = false,
  showValueLabel = false,
  label,
  className,
  'aria-label': ariaLabel,
  ...props
}: ProgressBarProps) {
  return (
    <Progress.Root
      {...props}
      value={isIndeterminate ? null : value}
      max={max}
      aria-label={label ? undefined : ariaLabel}
      className={cn(styles.root, styles[size], styles[variant], isRounded && styles.rounded, className)}
    >
      {label && <Progress.Label className={styles.label}>{label}</Progress.Label>}
      <div className={styles.row}>
        <Progress.Track className={styles.track}>
          <Progress.Indicator className={styles.indicator} />
        </Progress.Track>
        {showValueLabel && !isIndeterminate && <Progress.Value className={styles.value} />}
      </div>
    </Progress.Root>
  )
}

.root {
  --progress-height: var(--space-2);
  --progress-fill: var(--primary-text);
  display: grid;
  gap: var(--space-1-5);
  inline-size: 100%;
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--foreground);
}

.sm {
  --progress-height: var(--space-1);
}
.md {
  --progress-height: var(--space-2);
}
.lg {
  --progress-height: var(--space-3);
}

/* The fill is what carries the value, so it must reach 3:1 against the
   track (--secondary). The accent solids do not all manage that — amber's
   is about 2.9:1 on white — so each variant takes a colour measured at
   4.5:1 on the page as text, which keeps it at 3:1 or better on the track. */
.primary {
  --progress-fill: var(--primary-text);
}
.accent {
  --progress-fill: var(--foreground);
}
.secondary {
  --progress-fill: var(--muted-foreground);
}
.destructive {
  --progress-fill: var(--danger-text);
}

.label {
  font-weight: 500;
}

.row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.track {
  position: relative;
  flex: 1;
  block-size: var(--progress-height);
  overflow: hidden;
  background: var(--secondary);
}

.rounded .track,
.rounded .indicator {
  border-radius: 9999px;
}

.indicator {
  display: block;
  block-size: 100%;
  background: var(--progress-fill);
  transition: inline-size 200ms;
}

/* Indeterminate: a third-width bar sliding across. */
.indicator[data-indeterminate] {
  position: absolute;
  inset-block: 0;
  inline-size: 33%;
  animation: slide 1.4s ease-in-out infinite;
}

@keyframes slide {
  from {
    inset-inline-start: -33%;
  }
  to {
    inset-inline-start: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .indicator {
    transition: none;
  }
  .indicator[data-indeterminate] {
    animation-duration: 4s;
  }
}

.value {
  min-inline-size: 4ch;
  font-variant-numeric: tabular-nums;
  text-align: end;
  color: var(--muted-foreground);
}
